// Keep a straight product picture by default; create one 3D model only on request.
const instances=[];
const original=document.querySelector('#config-board');
if(original){const host=document.createElement('div');host.className='keyboard-studio picture-first';original.before(host);original.classList.add('studio-fallback');const modes=document.createElement('div');modes.className='preview-modes';modes.setAttribute('role','group');modes.setAttribute('aria-label','Keyboard preview');modes.innerHTML='<button type="button" data-mode="picture" aria-pressed="true">Product photo</button><button type="button" data-mode="model" aria-pressed="false">3D view</button><span>EN + RU</span>';host.append(modes,original);let viewer=null;
function showMode(mode){if(mode==='model'&&!viewer){try{viewer=new KeyboardViewer(host,false);if(!viewer.renderer)throw Error('WebGL unavailable');instances.push(viewer);}catch(err){host.querySelector('.viewer-stage')?.remove();host.querySelector('.viewer-toolbar')?.remove();host.classList.remove('has-3d');viewer=null;const status=document.querySelector('#status');if(status)status.textContent='The 3D view is unavailable in this browser. Your keyboard picture is still available.';return;}}const model=mode==='model';host.classList.toggle('has-3d',model);if(viewer){viewer.stage.hidden=!model;viewer.toolbar.hidden=!model;if(model){viewer.resize();viewer.view('angle');viewer.update(globalThis.getKeyboardDesign?.());}}modes.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.mode==='model')===model)));const caption=document.querySelector('.art-caption span:last-child');if(caption)caption.textContent=model?'3D CONCEPT VIEW · EN + RU':globalThis.getKeyboardDesign?.().m==='mountain'?'REFERENCE PHOTO · EN + RU':'PRODUCT PICTURE · EN + RU';}
document.addEventListener('keyboard-model-change',()=>{if(!viewer)return;const active=host.classList.contains('has-3d');instances.splice(instances.indexOf(viewer),1);viewer.dispose();viewer=null;host.classList.remove('has-3d');showMode(active?'model':'picture');});
modes.addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(b)showMode(b.dataset.mode);});showMode('picture');}
let queued=false;function sync(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;const state=globalThis.getKeyboardDesign?.();if(state){const names=[['recap-case',state.m==='mountain'?globalThis.mountainDesign.variants[state.v||0].name:['Silver aluminum','Ivory','Deep blue','Black'][state.c]],['recap-color',state.m==='mountain'?'Cream + mountain artwork':['Milk','Denim blue','Sand honey','Ice blue','Muted wine','Graphite'][state.k]],['recap-switch',{linear:'Linear',tactile:'Tactile',clicky:'Clicky'}[state.s]]];for(const [id,value] of names){const el=document.getElementById(id);if(el)el.textContent=value;}}if(instances.some(v=>v.model!==(state.m||'character')))document.dispatchEvent(new Event('keyboard-model-change'));instances.filter(v=>!v.hero).forEach(v=>v.update(state));const caption=document.querySelector('.art-caption span:last-child');if(caption)caption.textContent=document.querySelector('.keyboard-studio.has-3d')?'3D CONCEPT VIEW · EN + RU':state.m==='mountain'?'REFERENCE PHOTO · EN + RU':'PRODUCT PICTURE · EN + RU';});}document.addEventListener('click',sync);document.addEventListener('change',sync);

